<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Integration\CustomerPolicy;
use CetechDeliveryEngine\Application\CustomerPolicy\PolicyNativeOrderFacts as Facts;
use CetechDeliveryEngine\Infrastructure\WordPress\{OperationConnection,OperationConnectionMysqliTransport};
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyProofTransport;
use CetechDeliveryEngine\Tests\Support\Operation\OperationProofDatabase as DB;
use PHPUnit\Framework\Attributes\Group;
use PHPUnit\Framework\TestCase;
/** Actual HPOS/CPT raw transport bounds, independently of native-object and packet authority. */
#[Group('rule-lifecycle-real-db')]
final class CustomerPolicyNativeReadRealDatabaseTest extends TestCase {
 private \mysqli$db;private string$prefix;private array$transports=[];
 protected function setUp():void{
  $this->db=DB::connect();$this->prefix=DB::prefix();
  $tables=[
   'woocommerce_order_items'=>'order_item_id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,order_item_name longtext NOT NULL,order_item_type varchar(200) NOT NULL,order_id bigint unsigned NOT NULL,KEY order_id(order_id)',
   'woocommerce_order_itemmeta'=>'meta_id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,order_item_id bigint unsigned NOT NULL,meta_key varchar(255),meta_value longtext,KEY order_item_id(order_item_id)',
   'posts'=>'ID bigint unsigned NOT NULL PRIMARY KEY,post_type varchar(20) NOT NULL,post_status varchar(20) NOT NULL',
   'postmeta'=>'meta_id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,post_id bigint unsigned NOT NULL,meta_key varchar(255),meta_value longtext,KEY post_id(post_id)',
   'wc_orders'=>'id bigint unsigned NOT NULL PRIMARY KEY,status varchar(20) NOT NULL,currency varchar(10) NOT NULL,total_amount decimal(26,8) NOT NULL,tax_amount decimal(26,8) NOT NULL,customer_id bigint unsigned NOT NULL,payment_method varchar(100) NOT NULL,payment_method_title text NOT NULL,transaction_id varchar(100) NOT NULL',
   'wc_order_operational_data'=>'order_id bigint unsigned NOT NULL PRIMARY KEY,order_key varchar(100) NOT NULL,shipping_total_amount decimal(26,8) NOT NULL,shipping_tax_amount decimal(26,8) NOT NULL,date_paid_gmt datetime NULL',
   'wc_order_addresses'=>'id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,order_id bigint unsigned NOT NULL,address_type varchar(20) NOT NULL,country varchar(10),state varchar(100),city varchar(100),postcode varchar(100),address_1 text,address_2 text',
   'wc_orders_meta'=>'id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,order_id bigint unsigned NOT NULL,meta_key varchar(255),meta_value longtext,KEY order_id(order_id)',
  ];foreach($tables as$suffix=>$sql)DB::execute($this->db,"CREATE TABLE `{$this->prefix}{$suffix}` ({$sql}) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  DB::execute($this->db,"INSERT INTO `{$this->prefix}woocommerce_order_items` (order_item_id,order_item_name,order_item_type,order_id) VALUES (91,'Owned native item','line_item',77)");DB::execute($this->db,"INSERT INTO `{$this->prefix}posts` VALUES(77,'shop_order','wc-pending')");DB::execute($this->db,"INSERT INTO `{$this->prefix}wc_orders` VALUES(77,'wc-pending','GHS',27,0,0,'cetech_r24_local','Owned local payment','')");DB::execute($this->db,"INSERT INTO `{$this->prefix}wc_order_operational_data` VALUES(77,'owned-order-key',7,0,NULL)");
 }
 protected function tearDown():void{foreach($this->transports as$t)$t->force_close();if(isset($this->db,$this->prefix)){foreach(['woocommerce_order_itemmeta','woocommerce_order_items','postmeta','posts','wc_order_addresses','wc_order_operational_data','wc_orders_meta','wc_orders']as$suffix)DB::execute($this->db,"DROP TABLE IF EXISTS `{$this->prefix}{$suffix}`");$this->db->close();}}
 private function owner():OperationConnection{$t=new CustomerPolicyProofTransport(OperationConnectionMysqliTransport::connect((string)(getenv('CETECH_DE_REAL_DB_HOST')?:'127.0.0.1'),(string)(getenv('CETECH_DE_REAL_DB_USER')?:'root'),(string)(getenv('CETECH_DE_REAL_DB_PASSWORD')?:''),(string)getenv('CETECH_DE_REAL_DB_NAME'),(int)(getenv('CETECH_DE_REAL_DB_PORT')?:3306)));$this->transports[]=$t;return new OperationConnection(1,$this->prefix,$t,'utf8mb4','utf8mb4_unicode_ci');}
 private function metadata(string$table,string$key,?string$value):void{$column=str_contains($table,'itemmeta')?'order_item_id':(str_contains($table,'wc_orders_meta')?'order_id':'post_id');$id='order_item_id'===$column?91:77;$statement=$this->db->prepare("INSERT INTO `{$this->prefix}{$table}` ({$column},meta_key,meta_value) VALUES (?,?,?)");self::assertNotFalse($statement);self::assertTrue($statement->bind_param('iss',$id,$key,$value));self::assertTrue($statement->execute());$statement->close();}
 private function read(bool$hpos):array{$s=$this->owner();self::assertTrue($s->begin());try{return Facts::read_physical($s,77,$hpos);}finally{if($s->in_transaction())self::assertTrue($s->rollback());self::assertTrue($s->retire());}}
 private function refuse(bool$hpos):void{$failed=false;try{$this->read($hpos);}catch(\RuntimeException){$failed=true;}self::assertTrue($failed,'Unbounded native policy bytes escaped.');}
 private function blob_reads():array{return array_values(array_filter(end($this->transports)->sql,static fn(string$sql):bool=>str_starts_with($sql,'SELECT m.meta_id')||str_starts_with($sql,'SELECT id AS meta_id')||str_starts_with($sql,'SELECT meta_id,meta_key')));}
 public function test_both_actual_backends_preserve_unknown_and_duplicate_bytes_without_decoding():void{
  foreach([false,true]as$hpos){$root=$hpos?'wc_orders_meta':'postmeta';$this->metadata($root,Facts::META_MANIFEST,'{"format":99,"opaque":"café"}');$this->metadata($root,Facts::META_MANIFEST,'{"format":99,"opaque":"café"}');$this->metadata('woocommerce_order_itemmeta',Facts::META_PACKET,'{"format":99}');$raw=$this->read($hpos);self::assertCount(2,$raw['order_meta']);self::assertSame('{"format":99,"opaque":"café"}',$raw['order_meta'][0]['meta_value']);self::assertSame($raw['order_meta'][0]['meta_value'],$raw['order_meta'][1]['meta_value']);self::assertSame('77',$raw['order'][0][$hpos?'id':'ID']);DB::execute($this->db,"DELETE FROM `{$this->prefix}woocommerce_order_itemmeta`");}
 }
 public function test_oversized_policy_blob_is_refused_before_any_item_blob_fetch():void{foreach([false,true]as$hpos){$this->metadata('woocommerce_order_itemmeta',Facts::META_PACKET,str_repeat('x',327681));$before=(string)DB::scalar($this->db,"SELECT SHA2(meta_value,256) FROM `{$this->prefix}woocommerce_order_itemmeta` LIMIT 1");$this->refuse($hpos);self::assertSame([],$this->blob_reads());self::assertSame($before,(string)DB::scalar($this->db,"SELECT SHA2(meta_value,256) FROM `{$this->prefix}woocommerce_order_itemmeta` LIMIT 1"));DB::execute($this->db,"DELETE FROM `{$this->prefix}woocommerce_order_itemmeta`");}}
 public function test_aggregate_item_blob_budget_refuses_before_any_raw_payload_transport():void{foreach([false,true]as$hpos){$this->metadata('woocommerce_order_itemmeta','unowned-native-a',str_repeat('a',2200000));$this->metadata('woocommerce_order_itemmeta','unowned-native-b',str_repeat('b',2200000));$this->refuse($hpos);self::assertSame([],$this->blob_reads());DB::execute($this->db,"DELETE FROM `{$this->prefix}woocommerce_order_itemmeta`");}}
 public function test_null_physical_policy_value_is_presence_and_refuses_before_blob_fetch():void{foreach([false,true]as$hpos){$this->metadata('woocommerce_order_itemmeta',Facts::META_PACKET,null);$this->refuse($hpos);self::assertSame([],$this->blob_reads());self::assertSame('1',(string)DB::scalar($this->db,"SELECT COUNT(*) FROM `{$this->prefix}woocommerce_order_itemmeta` WHERE meta_value IS NULL"));DB::execute($this->db,"DELETE FROM `{$this->prefix}woocommerce_order_itemmeta`");}}
 public function test_metadata_row_sentinel_refuses_before_loading_raw_payloads():void{$values=implode(',',array_fill(0,500,"(91,'unowned','x')"));for($i=0;$i<24;++$i)DB::execute($this->db,"INSERT INTO `{$this->prefix}woocommerce_order_itemmeta` (order_item_id,meta_key,meta_value) VALUES {$values}");$this->metadata('woocommerce_order_itemmeta','unowned-final','x');foreach([false,true]as$hpos){$this->refuse($hpos);self::assertSame([],$this->blob_reads());}self::assertSame('12001',(string)DB::scalar($this->db,"SELECT COUNT(*) FROM `{$this->prefix}woocommerce_order_itemmeta`"));}
 public function test_unbounded_native_item_name_is_refused_without_raw_name_transport():void{DB::execute($this->db,"UPDATE `{$this->prefix}woocommerce_order_items` SET order_item_name='".str_repeat('x',2049)."' WHERE order_item_id=91");foreach([false,true]as$hpos){$this->refuse($hpos);$t=end($this->transports);$queries=array_values(array_filter($t->replies,static fn(array$r):bool=>str_starts_with($r['sql'],'SELECT order_item_id,order_item_type,CASE')));self::assertCount(1,$queries);self::assertNull($queries[0]['result']->rows[0]['order_item_name']);self::assertSame([],$this->blob_reads());}}
 public function test_absent_or_retired_transaction_owner_cannot_read_native_rows():void{$s=$this->owner();$count=count(end($this->transports)->sql);$failed=false;try{Facts::read_physical($s,77,true);}catch(\RuntimeException){$failed=true;}self::assertTrue($failed);self::assertSame($count,count(end($this->transports)->sql));self::assertTrue($s->retire());$failed=false;try{Facts::read_physical($s,77,false);}catch(\RuntimeException){$failed=true;}self::assertTrue($failed);self::assertSame($count,count(end($this->transports)->sql));}
}
